INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'Geography', 'Unit 4', 'Molarum Grade 10 — Geography Unit 4: Population of Africa', 'Source-grounded Molarum Grade 10 Geography questions for Unit 4: Population of Africa.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('e0b731e1-a544-4433-8c2c-536e5c06e705'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'According to Table 4.1 in the excerpt, which region had a population of 133 million in 1900?', 'Africa', 'Table 4.1 in the excerpt lists Africa''s population as 133 million in 1900, so Africa is the correct region.', 0),('28af56c6-6418-4cb6-8acf-88b8014d8708'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'The excerpt states Asia’s share of the world population rose from 58% to which percentage between 1970 and 2021?', '61%', 'The excerpt explicitly states that Asia’s share rose from 58% to 61% during the period referenced, so 61% is correct.', 1),('09527999-682b-4e0b-8cd8-f35a08538553'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which continent had only about 43 million inhabitants, making it the least populated according to the excerpt?', 'Oceania', 'The excerpt states that Oceania had only 43 million people, making it the least populated continent, so Oceania is correct.', 2),('fe0b33e0-75b2-467e-874d-74965129e296'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which region is listed with a population of about 4,641 million in 2020 in Table 4.1?', 'Asia', 'Table 4.1 shows Asia''s population as 4,641 million in 2020, therefore Asia is the correct answer.', 3),('ec6062f6-820d-4985-8f7a-92cad44734a7'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which expression matches the Rule of 70 for calculating population doubling time as given in the excerpt?', 'dt = 70 / r', 'The excerpt gives the Rule of 70 formula for doubling time as dt = 70 ÷ r, so dt = 70 / r is the correct expression.', 4),('2affc58e-2200-42d2-8658-7ec3d95989a1'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which of the following is NOT listed in the excerpt as an interrelated factor responsible for Africa’s rapid population growth?', 'Rapid decrease in fertility rates', 'The excerpt lists high birth rates, low contraceptive use, and declining death rates as factors; a rapid decrease in fertility rates is not listed as a cause of rapid growth.', 5),('664c4065-9f82-4ee8-8700-785415e26d5c'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which of the following is NOT one of the four ways population can change in an area as listed in the excerpt?', 'The marriage rate rises in the area', 'The excerpt lists births, deaths, in-migration, and out-migration as the four ways population changes; marriage rate is not included in that list.', 6),('27dc3628-d7e9-443e-8adc-eb726f06d4c8'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'According to Table 4.4, which African region had the highest Total Fertility Rate (TFR) in 2004?', 'Central Africa', 'Table 4.4 shows Central Africa with a TFR of 6.4 in 2004, the highest among the listed regions for that year.', 7),('7deb6bca-784c-49ad-80de-f168e88a7f04'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which region is recorded with a Total Fertility Rate of 2.4 children per woman in 2020 in Table 4.4?', 'Southern Africa', 'Table 4.4 lists Southern Africa as having a TFR of 2.4 in 2020, so Southern Africa is correct.', 8),('23651d88-8063-4e11-89ca-9f6cfab60bf9'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which country is shown in Table 4.5 as having a crude birth rate of 49 per 1,000 population in 2020?', 'Somalia', 'Table 4.5 indicates Somalia had a crude birth rate of 49/1000 in 2020, making Somalia the correct choice.', 9),('69f2d6c9-9640-47ee-85f5-0f2057bb0605'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which measure is defined in the excerpt as the number of maternal deaths per 100,000 live births?', 'Maternal Mortality Ratio (MMR)', 'The excerpt defines the Maternal Mortality Ratio as the number of maternal deaths per 100,000 live births, so MMR is correct.', 10),('1421c766-b33b-4f69-8eb6-02cdc1056d8b'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which African region had a life expectancy at birth of 74 years in 2020, according to Table 4.7?', 'Northern Africa', 'Table 4.7 shows Northern Africa with a life expectancy of 74 years in 2020, so Northern Africa is correct.', 11),('109ae537-9d8b-4c4a-8ff2-b506c25b341a'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'What percentage of the world’s population did Africa represent in the excerpt’s Table 4.2?', '17.5%', 'Table 4.2 in the excerpt lists Africa''s share of the world population as 17.5 percent, so 17.5% is correct.', 12),('da253c56-b9a9-441d-8458-f3c3d5072b26'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which type of population pyramid is characteristic of most developing countries and is described as having a broad base and tapering apex?', 'Expansive pyramid', 'The excerpt describes the expansive pyramid as having a broad base and tapering apex typical of developing countries, so Expansive pyramid is correct.', 13),('b27a6ab4-13c9-4cfa-85e4-8e9bc48a3025'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'What was Africa’s median age by mid-2020 as stated in the excerpt?', '19.7 years', 'The excerpt explicitly gives Africa''s median age as 19.7 years by mid-2020, so 19.7 years is the correct answer.', 14),('2aedb556-239c-46da-8ad9-5d5a2c0e72f7'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which outcome does the excerpt state is expected as mortality declines in Africa?', 'An ageing population requiring planning', 'The excerpt states that with reduced mortality, Africa should expect and plan for an ageing population, making that option correct.', 15),('f56354cd-b6a0-431f-81dc-9ac869a40925'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which African region recorded the highest infant mortality rate (IMR) per 1,000 live births in Table 4.6 for 2020?', 'Central Africa', 'Table 4.6 shows Central Africa with the highest IMR at 62 deaths per 1,000 live births in 2020, so Central Africa is correct.', 16),('a9131ef6-3eac-4e4c-8a7a-584c527eed27'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as a cause of the relatively high death rate in Africa?', 'Low standard of living', 'The excerpt lists low standard of living among the causes of Africa''s relatively high death rate, so that option is correct.', 17),('d8d2c764-720b-4d39-8ef9-31b7c9abb070'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'The excerpt projects that Africa’s population could peak at about 2.5 billion in 2050, representing approximately what percentage of the world total?', '25%', 'The excerpt states that a projected peak of 2.5 billion would represent about 25% of the world''s population, so 25% is correct.', 18),('8782adf6-540c-4a76-854a-54df33ee88b6'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'multiple_choice', 'The excerpt states Sub-Saharan Africa experiences about what annual rate of natural increase?', '3% per year', 'The excerpt indicates Sub-Saharan Africa has a natural increase rate of about 3% per year, so 3% per year is correct.', 19),('46492213-1f55-41ce-85c0-5df72d0990f2'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'true_false', 'The Rule of 70 computes doubling time by dividing the growth rate by 70.', 'False', 'The excerpt states the Rule of 70 divides 70 by the growth rate (dt = 70 / r), not the growth rate by 70, so the statement is false.', 20),('f019a7d0-0a42-4bc8-841d-a1977afd76d3'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'true_false', 'The excerpt reports Africa’s fertility rate as 4.5 children per woman in 2017.', 'True', 'The excerpt cites Africa''s fertility as 4.5 children per woman in 2017, so the statement is true.', 21),('bb926f3c-8731-458b-8156-b69c745198b9'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'true_false', 'By mid-2020 the excerpt states that life expectancy at birth for the whole of Africa was 64 years.', 'True', 'Table 4.7 and the accompanying text state Africa''s average life expectancy at birth was 64 years by mid-2020, so the statement is true.', 22),('22eee684-bad4-481d-89a9-609200546ebc'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'true_false', 'The excerpt indicates the infant mortality rate for Northern Africa was 62 per 1,000 live births in 2020.', 'False', 'The excerpt shows Northern Africa''s IMR as 22 per 1,000 live births in 2020; 62/1,000 refers to Central Africa, so the statement is false.', 23),('8b622e37-4512-4c54-8444-57b64f458b67'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Define Total Fertility Rate (TFR) as given in the excerpt.', 'The average number of children a woman would give birth to during her lifetime (ages 15–49) if she experienced the present age-specific fertility rates.', 'The excerpt defines TFR as the average number of children a woman would have during her childbearing years under current age-specific fertility rates, so this definition matches the text.', 24),('4c0c2a49-c9d2-4243-8133-7318105a07b7'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Write the demographic balancing equation shown in the excerpt (use the same symbols).', 'Pt - Po = B - D + I - O', 'The excerpt presents the balancing equation as Pt - Po = B - D + I - O, where Pt and Po are end and beginning populations and B,D,I,O are births, deaths, in- and out-migration.', 25),('2e4863a2-d804-4c98-80ee-1f53cc632774'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'List three interrelated demographic or socioeconomic factors responsible for Africa’s rapid population growth mentioned in the excerpt.', 'High crude birth rates; low rates of contraceptive use; decline in infant and maternal mortality (decline in overall death rates).', 'The excerpt lists several factors including high crude birth rates, low contraceptive use, and declines in infant, maternal and overall death rates, any three of which answer the question.', 26),('f7399783-797f-4560-854b-694c8ab0568a'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'State two challenges that Africa’s rapid population growth has brought, as described in the excerpt.', 'Producing sufficient food to feed the population; providing adequate healthcare and education to the large youth population.', 'The excerpt explains challenges such as producing enough food and providing healthcare and education for the rapidly growing and youthful population, so these two are supported.', 27),('896fd020-c037-4774-8023-fd6c4a1b3204'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Define the Crude Birth Rate (CBR) and state its unit as given in the excerpt.', 'CBR is the number of live births in a given year per 1,000 mid-year total population; the unit is births per 1,000 population.', 'The excerpt defines CBR as live births per 1,000 mid-year population, so this definition and unit follow the text exactly.', 28),('af064c7d-34a8-4812-8683-a9078c7a5417'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'What is population doubling time and how is it computed using the method given in the excerpt?', 'Doubling time is the time it takes for a population to double in size and is computed using the Rule of 70: dt = 70 / r (where r is the growth rate).', 'The excerpt defines doubling time as the period for a population to double and gives the Rule of 70 formula dt = 70 ÷ r, so this response follows the excerpt.', 29),('73e4cd69-0ee8-4d81-8e4a-a76a5b753bfe'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'According to Table 4.7 in the excerpt, what was the life expectancy at birth for Western Africa in 2020 (in years)?', '59', 'Table 4.7 lists Western Africa''s life expectancy at birth as 59 years in 2020, so 59 is the correct value from the excerpt.', 30),('8d892218-107b-4bb9-87a1-a2bfc6c4374c'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Explain why an expansive population pyramid indicates high dependency pressure and resource demand, using points from the excerpt.', 'An expansive pyramid has a broad base indicating a large proportion of children, which raises dependency ratios and increases demand for food, education, health services, and housing as described in the excerpt.', 'The excerpt explains that a broad base reflects many young dependents and that high fertility increases demand for basic services and resources, linking the pyramid shape to dependency and resource pressure.', 31),('723c5ee3-64ff-4daa-8077-1dfac10eb489'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Using the excerpt''s Rule of 70 example: If Ethiopia''s population growth rate is 2.5, how many years does the excerpt calculate it would take to double its population? (Use the formula dt = 70 / r.)', '28', 'The excerpt applies dt = 70 ÷ 2.5 and shows dt = 28 years for Ethiopia, so 28 years is the computed doubling time.', 32),('11e08b33-5883-4458-805f-38819346d964'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'The excerpt states Africa''s growth rate was 2.5% per year; using dt = 70 / r, how many years would it take Africa to double in size at that rate?', '28', 'Using the Rule of 70 as shown in the excerpt, dt = 70 ÷ 2.5 = 28 years, so Africa''s doubling time at 2.5% is 28 years.', 33),('f9ae4c89-5331-41a8-8ec9-7bbcf7d7e742'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Using the CBR example in the excerpt: if Country X had 2,407,500 live births and a mid-year population of 53,500,000, what CBR per 1,000 does the excerpt compute? (CBR = B / P × 1000)', '45', 'The excerpt computes CBR = 2,407,500 ÷ 53,500,000 × 1000 = 45 births per 1,000 mid-year population, so 45 is the result shown.', 34),('24e0d7b9-c11c-4174-81a9-f76707d8dda2'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Using the CDR example in the excerpt: if Country X had 856,000 deaths and a mid-year population of 53,500,000, what crude death rate per 1,000 does the excerpt calculate? (CDR = D / P × 1000)', '16', 'The excerpt calculates CDR = 856,000 ÷ 53,500,000 × 1000 = 16 deaths per 1,000, so 16 is the computed value.', 35),('3a516713-c6eb-4e27-876e-d4cf0d3cef3c'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'Using the sex ratio example in the excerpt: if a country has 3.6 million males and 4.0 million females, what sex ratio (number of males per 100 females) does the excerpt compute? (Sex Ratio = (male / female) × 100)', '90', 'The excerpt''s example gives Sex Ratio = (3.6 million ÷ 4.0 million) × 100 = 90 males per 100 females, so 90 is correct.', 36),('4e56fe9f-6e74-44ce-819a-48730ac0e137'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'From the excerpt''s MMR example: if Country Z had 10,000 maternal deaths and 3,500,000 live births in 2020, what Maternal Mortality Ratio per 100,000 does the excerpt compute? (MMR = maternal deaths / live births × 100,000)', '286', 'The excerpt computes MMR = 10,000 ÷ 3,500,000 × 100,000 = 286 maternal deaths per 100,000 live births, so 286 is the result shown.', 37),('c415be97-4040-4c8a-807c-cd556e522544'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'According to Table 4.2 in the excerpt, what percentage of the world’s population did Africa represent?', '17.5', 'Table 4.2 explicitly lists Africa''s percentage share of world population as 17.5, so 17.5 is the stated figure in the excerpt.', 38),('bf9ee9f0-8c11-46c7-8dfd-6dbf6661344d'::uuid, 'ec649db5-9258-431d-8c44-015e2e9e656e'::uuid, 'fill_blank', 'What average life expectancy at birth for the whole of Africa in 2020 does Table 4.7 give in the excerpt?', '64', 'Table 4.7 and the text state Africa''s average life expectancy at birth was 64 years in 2020, so 64 years is the figure from the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
